"""Generate report from frozen raw measurements, with explicit interpretation limits."""
import json,statistics
from pathlib import Path
R=Path(__file__).resolve().parents[2];D=R/'results/asr-small-20261018';summary=json.loads((D/'standalone-summary.json').read_text());mixed=json.loads((D/'paced-mixed-summary.json').read_text());clean=json.loads((D/'cleanup-chunks.json').read_text())
names={'stream':'流式 Zipformer Small CTC','offline':'离线 Zipformer Small CTC','para':'Paraformer 中文小版','sense':'SenseVoice INT8','qwen':'Qwen3-ASR 0.6B INT8'}
text=['# 小 ASR 离线板端部署与竞争实测（2026-10-18）','','本轮已在板卡实际执行模型推理；Windows F 盘保存源码、离线权重、语料和原始结果，Mac 仅用于远程调度/资料中转。ASR 使用 ARM64 CPU / sherpa-onnx 1.13.8 / ONNX Runtime，**不是 NPU ASR**。NPU 继续运行已复现的 1B LLM。没有调用云端识别 API，没有采集家中麦克风录音，没有替换生产服务。','','## 推荐与边界','','优先将 **Silero VAD + Paraformer 小版**作为低延迟中文原型；将**离线 Zipformer Small**保留为更稳的对照/按需复核模型。复核策略尚未实现，也没有测双模型常驻开销。流式 Zipformer 内存最小，但当前强噪声识别和端点策略不足，暂不作为默认完整对话管线。','','该推荐仅基于 24 句公开普通话测试语音及有限合成噪声，不能代替家庭场景、方言、麦克风、真实背景噪声验收。人名需要用户词表或确认机制，不能由这一组结果宣称已解决。','','## 已部署模型与可复现位置','','- F 盘模型：`F:\\Files\\OPi-Lab\\asr-small-models-20261018\\models`。','- F 盘代码：`F:\\Files\\OPi-Lab\\repos\\OragnePi-3W_ForVLM\\research\\asr-small`。','- 原始证据：同仓库 `results/asr-small-20261018`。','- 板端：`/opt/opi-vlm/asr-small-20261018`；复用已有 `audio-lab-20261018/deps`，无需安装或修改系统依赖。','- CPU 固定 2,3、推理单线程；NPU LLM 主机线程 CPU6,7。','- 每次板端操作经过 Windows hostlock 和板端 flock；同跑测试由一个协调器持锁。','- `model-sources.json`、各运行 manifest 和 `*-scripts/` 保存来源、SHA-256、执行脚本快照。下载/加载时间不计入下表常驻推理时间。','','| 模型 | 权重 ONNX 大小 | 版本 |','|---|---:|---|','| 流式 Zipformer | 25.1 MiB | 2025-04-01 |','| 离线 Zipformer | 59.8 MiB | 2025-07-16 |','| Paraformer 小版 | 78.0 MiB | 2024-03-09 |','| Qwen 0.6B | 937.0 MiB 左右（3个ONNX；状态见下方Qwen实验） | 2026-03-25包，发布资产2026-04-07更新 |','','模型文件体积不是参数量，不能据此猜参数数目。','','## 同语料质量与常驻推理','','AISHELL test 第一分片固定 seed20261018，24句、6位说话人、352个参考字、合计118.91秒，音频中位数4.947秒。按否定词/数字字符/其余随机分层抽样；数字字符组也包含“一些”等非数值用法，不称严格数字专项。镜像音频的24条转写与AISHELL官方原始转写全部一致。另4句各生成10dB/0dB白噪声，共8句，加3秒静音。前三候选与SenseVoice使用相同33条输入，Qwen采用其预先固定的14条子集。','','前三候选与SenseVoice各33输入×2遍，另有单独不计分预热。CER仅去空白/标点/控制字符，不归一化日期、数字、名字、否定词或简繁体。时间为特征处理+识别API，非纯神经网络kernel，也非说完后整机端到端延迟。','','| 模型 | 干净CER | 10dB CER | 0dB CER | 干净句p50 / p95 | 总RTF | 峰值RSS / 采样PSS | 加载秒 |','|---|---:|---:|---:|---:|---:|---:|---:|']
for key,v in summary.items():
 if v['kind']=='qwen':continue
 g=v['groups'];text.append(f"| {names[v['kind']]} | {g['clean']['cer']:.2%} | {g['white-10db']['cer']:.2%} | {g['white-0db']['cer']:.2%} | {v['latency_p50']:.3f} / {v['latency_p95']:.3f} s | {v['rtf_aggregate']:.3f} | {v['peak_rss_mib']:.0f} / {v['peak_sampled_pss_mib']:.0f} MiB | {v['load_seconds']:.2f} |")
text+=['','流式表内时间为不节拍回放整段、含额外2秒静音处理的计算总耗时；不能把1.65秒理解成说完后再等1.65秒，也不能与离线模型当成完全相同计算量。加载测试未清页缓存，不称冷启动。独跑温度并未严格相同，性能结果保留实测条件。','','干净语音两遍输出一致，列出的否定/日期字符串均保留；三款小模型和SenseVoice都把“朱圣祎”写成“朱胜伟”，触发了出结果前保存的保守Qwen试验条件。0dB下流式出现丢否定、日期缺失和空输出；离线Zipformer在选中日期/否定句仍保留关键串，但人名句同样错误。不要将此扩展为对所有否定/日期都可靠。','','静音时，Paraformer输出“我们我我的我啊”，SenseVoice输出“我”，两款Zipformer为空。额外部署Silero VAD门控探针：33条输入逐条跑VAD，24条干净语音全放行，静音阻断；并实际跑了语音→Paraformer和静音→跳过ASR两例。该探针是整句语音存在门控，不是已经验收的连续分句服务。','','## 流式节拍与端点','','80ms一块、按真实时钟投喂，测试5条干净句、同一句10dB/0dB与静音，追加2秒静音，单句独立stream。记录逐块due/start/end和文本变更；不因端点重置stream，便于核对整句最终转写。','','- 干净语音首次部分文字约1.60–1.72秒。','- 干净语音最终文本最后一次变更相对文件结束约−0.17～+0.36秒；这是事后稳定时间，不是可在线保证的最终确认。','- 0.5秒端点规则出现句中提前触发：日期句在输入2.72秒时仅识别到“中心网五月七日”就报端点，后半句尚未完成。正式对话若立即reset会截句，当前不能上线此端点策略。','- 部分块计算约158ms超过80ms；采样最大起始落后约112–215ms、最大完成落后约192–294ms，尾部能追上。不是每80ms硬实时保证。','- 8例强制finish均未改变文本；自然端点、强制finish、部分文本均保留原始记录。','- 文件结束不是人工标注的人声结束，负的尾延迟反映文件尾静音，不能称负的真实响应时间。','','## 与NPU LLM竞争','','P64固定前缀，D64/D256动态输入，每条件2次，第二轮反向顺序。ASR以连续离线推理形成压力；每个条件每长度各2次，Qwen另有匹配基线，不跨批比较绝对增减；不是四种ASR同时运行，也不是实际持续麦克风流式链。每次输出128token，24decoder层和head都在NPU。','','| 场景 | ASR条件 | LLM解码均值 | 相对该批基线 | TTFT范围 | 最低可用内存 |','|---|---|---:|---:|---:|---:|']
for name,conds in mixed['mixed'].items():
 for k,v in conds.items():text.append(f"| {name} | {names.get(k,k)} | {v['tps_mean']:.3f} token/s | {v['tps_change_percent']:+.2f}% | {min(v['ttft']):.3f}–{max(v['ttft']):.3f} s | {v['min_available_mib']:.0f} MiB |")
text+=['','基线和并行温度存在差异、每条件仅2次；D64基线两次本身波动约1.9%，不得将并行略高解读为提速。TTFT采用现有runner响应计时，排除模型加载和固定前缀准备，不代表持久KV服务。每次核验固定反馈输出token相同、driver释放后为0，竞争实交集见summary原始证据。','','系统已有swap存量：独跑第一条采样已约454MiB，随后到527MiB，D64期间到约655MiB，D256期间峰值670.75MiB。没有清swap，也没有凭此断言模型内存泄漏。首次三模型测试缺少完整进程换页归因，因此swap增加不能归因到单一ASR。进程RSS/PSS不含所有NPU驱动内存，也不能等同整机占用。','','## Qwen 0.6B 条件实验','']
q=[v for v in summary.values() if v['kind']=='qwen']
if q:
 v=q[-1];text += [f"已实际部署并完成 {v['groups']['clean']['n']} 条干净语音及噪声/静音探针。该组为前面语料的固定子集，只有一遍，不能与24句完整CER直接横比。加载 {v['load_seconds']:.2f}秒，干净推理p50 {v['latency_p50']:.3f}秒、p95 {v['latency_p95']:.3f}秒，RTF {v['rtf_aggregate']:.3f}，峰值RSS {v['peak_rss_mib']:.0f}MiB。"]
else:text+=['Qwen结果尚未齐全，此文为过程稿，不能声称已完成Qwen。']
text+=['','## 存储清理','',f"按用户要求删除1430个旧GGUF传输分片及重试副本，每个先与保留完整GGUF对应字节范围逐字节相等校验。释放{clean['freed_bytes']/2**30:.2f}GiB，板卡可用空间由{clean['before']['free']/2**30:.2f}GiB增至{clean['after']['free']/2**30:.2f}GiB（此数为随后部署新ASR前）。完整模型、生产服务、NPU最高性能版本、实验结果均保留。清理清单含每片hash、原件、偏移和字节数。",'','## 来源与证据','','- [Sherpa流式Zipformer文档](https://k2-fsa.github.io/sherpa/onnx/pretrained_models/online-ctc/zipformer-ctc-models.html)','- [Paraformer文档](https://k2-fsa.github.io/sherpa/onnx/pretrained_models/offline-paraformer/paraformer-models.html)','- [Qwen3-ASR离线文档](https://k2-fsa.github.io/sherpa/onnx/qwen3-asr/pretrained.html)','- [发布资产](https://github.com/k2-fsa/sherpa-onnx/releases/tag/asr-models)','- [AISHELL官方数据/转写](https://huggingface.co/datasets/AISHELL/AISHELL-1)','- [测试分片来源](https://huggingface.co/datasets/carlot/AIShell)','- 本地原始文件：`corpus-manifest.json`、`official-reference-check.json`、`acceptance-clarification.json`、`standalone-summary.json`、`paced-mixed-summary.json`、`vad-gate.json`、`cleanup-chunks.json`及逐运行目录。','']
out=R/'docs/research/小ASR离线部署与LLM竞争报告-20261018.md';out.write_text('\n'.join(text));print(out)
